-- Real database/provider RPC integration. Every synthetic row is rolled back.
-- p_evaluation represents the trusted server evaluator, covered separately by
-- case-runtime-model.test.mjs; it is never accepted from a browser or Data API user.
BEGIN;
SET LOCAL statement_timeout='40s';
CREATE TEMP TABLE runtime_qa_result(label text, passed boolean);
CREATE TEMP TABLE runtime_qa_context(workspace uuid,actor uuid,template uuid,instance uuid,source uuid);
GRANT ALL ON runtime_qa_result,runtime_qa_context TO service_role;
SET LOCAL ROLE service_role;
DO $$
DECLARE w uuid; actor uuid; t uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); d uuid:=gen_random_uuid(); v uuid; ref uuid; evidence uuid; attempt uuid; subject uuid; binding uuid; result jsonb; snap jsonb; old_revision text; op uuid; payload jsonb; ev jsonb; manifest jsonb; blocked boolean; count_before int;
BEGIN
 SELECT m.workspace_id,m.user_id INTO w,actor FROM public.workspace_members m JOIN public.workspaces ws ON ws.id=m.workspace_id WHERE m.status='active' AND m.role='owner' AND (m.access_expires_at IS NULL OR m.access_expires_at>now()) AND coalesce((ws.organization_settings#>>'{case_review,separationOfDuties}')::boolean,false)=false LIMIT 1;
 IF w IS NULL THEN RAISE EXCEPTION 'QA_NO_FIXTURE_WORKSPACE'; END IF;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 INSERT INTO runtime_qa_context VALUES(w,actor,t,c,d);
 payload:=jsonb_build_object('name','QA CASE RUNTIME ROLLBACK','description','','case_type','QA','requirements_schema',jsonb_build_object('version',6,'workflowMode','simple','experience',jsonb_build_object('signAtClosure',false),'sections',jsonb_build_array(jsonb_build_object('id','section','title','QA','items',jsonb_build_array(jsonb_build_object('id','item','kind','requested_document','title','Contrato QA','required',true,'requiresReview',true,'reviewerRole','owner','requiresSignature',true,'allowedFormats',jsonb_build_array('pdf'),'maxSizeMb',50,'allowReplacement',true)))),'verifications',jsonb_build_array(jsonb_build_object('id','email','catalogKey','email_otp','title','Correo','required',true)),'stages',jsonb_build_array(jsonb_build_object('id','manual','catalogKey','custom','title','Confirmación QA','completionMode','manual','coordinatorRole','owner','activities','[]'::jsonb)),'reviewPolicy',jsonb_build_object('version',1,'reviewTiming','progressive','approval',jsonb_build_object('enabled',true,'role','owner'),'completion',jsonb_build_object('mode','manual','role','owner'))),'forms_schema','[]'::jsonb);
 result:=public.case_control_publish(t,actor,w,null,payload);
 IF (result->>'publication_version')::int<>1 THEN RAISE EXCEPTION 'QA_PUBLICATION'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.case_file_template_versions WHERE template_id=t AND published_by=actor) THEN RAISE EXCEPTION 'QA_PUBLISHER'; END IF;
 INSERT INTO runtime_qa_result VALUES('server publication and immutable version',true);
 result:=public.case_control_start(t,actor,'QA CASE RUNTIME ROLLBACK','QA sujeto',actor,jsonb_build_object('approver',actor,'closer',actor,'reviewers',jsonb_build_object('item',actor)),c,'qa@example.invalid');
 PERFORM public.case_control_start(t,actor,'QA CASE RUNTIME ROLLBACK','QA sujeto',actor,jsonb_build_object('approver',actor,'closer',actor,'reviewers',jsonb_build_object('item',actor)),c,'qa@example.invalid');
 IF (SELECT count(*) FROM public.case_files WHERE id=c)<>1 THEN RAISE EXCEPTION 'QA_DUPLICATE_START'; END IF;
 INSERT INTO runtime_qa_result VALUES('retry-safe start and role assignments',true);
 INSERT INTO public.documentos(id,documento_id,workspace_id,owner_id,file_name,file_hash_sha256,nombre,estado,participantes,blockchain_evidence_enabled)
 VALUES(d,'QA-'||d,w,actor,'qa.pdf',repeat('a',64),'QA ROLLBACK','en_proceso',jsonb_build_array(jsonb_build_object('id',actor,'user_id',actor,'email','qa@example.invalid','role','firmante','visible',true)),false);
 SELECT id INTO ref FROM public.document_participant_references WHERE document_id=d LIMIT 1;
 IF ref IS NULL THEN RAISE EXCEPTION 'QA_REFERENCE_NOT_PROJECTED'; END IF;
 INSERT INTO public.document_versions(workspace_id,document_id,version_number,status,sha256,storage_path,byte_size) VALUES(w,d,1,'sent',repeat('a',64),'qa/rollback.pdf',1024) RETURNING id INTO v;
 snap:=public.case_control_snapshot(c,actor,false); old_revision:=snap->>'revision';op:=gen_random_uuid();
 PERFORM public.case_control_attach(c,actor,old_revision,'item',d,'document',op);
 PERFORM public.case_control_attach(c,actor,old_revision,'item',d,'document',op);
 IF (SELECT count(*) FROM public.case_file_document_versions WHERE case_file_id=c)<>1 THEN RAISE EXCEPTION 'QA_DUPLICATE_BINDING'; END IF;
 INSERT INTO runtime_qa_result VALUES('version binding and attach idempotency',true);
 blocked:=false;BEGIN PERFORM public.case_control_attach(c,actor,old_revision,'item',d,'document',gen_random_uuid()); EXCEPTION WHEN serialization_failure THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_STALE_WRITE'; END IF;
 INSERT INTO runtime_qa_result VALUES('stale evidence revision denied',true);
 SELECT id INTO binding FROM public.case_file_documents WHERE case_file_id=c;
 ev:=jsonb_build_object('conditions',jsonb_build_array(jsonb_build_object('key','content:item','status','satisfied')),'eligible',false,'canApprove',false,'canSign',false,'reviewableIds',jsonb_build_array('item'),'operationalStatus','in_review','stageStatuses','[]'::jsonb);
 snap:=public.case_control_snapshot(c,actor,false);op:=gen_random_uuid();
 PERFORM public.case_control_apply(c,actor,snap->>'revision','review',op,ev,jsonb_build_object('itemId','item','decision','observed','reason','QA corregir','documentId',binding,'evidenceVersion',v,'evidenceHash',repeat('a',64)));
 IF NOT EXISTS(SELECT 1 FROM public.case_file_observations WHERE case_file_id=c AND template_item_id='item' AND status='open') THEN RAISE EXCEPTION 'QA_OBSERVATION'; END IF;
 snap:=public.case_control_snapshot(c,actor,false);
 PERFORM public.case_control_apply(c,actor,snap->>'revision','review',gen_random_uuid(),ev,jsonb_build_object('itemId','item','decision','accepted','documentId',binding,'evidenceVersion',v,'evidenceHash',repeat('a',64)));
 IF EXISTS(SELECT 1 FROM public.case_file_observations WHERE case_file_id=c AND status='open') THEN RAISE EXCEPTION 'QA_UNRESOLVED'; END IF;
 INSERT INTO runtime_qa_result VALUES('observations and independent accepted review',true);
 snap:=public.case_control_snapshot(c,actor,false);blocked:=false;
 BEGIN PERFORM public.case_control_apply(c,actor,snap->>'revision','approval',gen_random_uuid(),ev,'{"decision":"approved","snapshotId":"material"}'); EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_APPROVAL_NOT_READY' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_PREMATURE_APPROVAL'; END IF;
 INSERT INTO runtime_qa_result VALUES('approval waits for trusted conditions',true);
 ev:=jsonb_set(ev,'{canApprove}','true');
 PERFORM public.case_control_apply(c,actor,snap->>'revision','approval',gen_random_uuid(),ev,'{"decision":"corrections","reason":"QA global","itemIds":["item"],"snapshotId":"material"}');
 IF NOT EXISTS(SELECT 1 FROM public.case_file_observations WHERE case_file_id=c AND reason_code='approval' AND template_item_id='item') THEN RAISE EXCEPTION 'QA_TARGETED_CORRECTIONS'; END IF;
 INSERT INTO runtime_qa_result VALUES('global corrections retain affected item and reason',true);
 snap:=public.case_control_snapshot(c,actor,false);
 PERFORM public.case_control_apply(c,actor,snap->>'revision','review',gen_random_uuid(),ev,jsonb_build_object('itemId','item','decision','accepted','documentId',binding,'evidenceVersion',v,'evidenceHash',repeat('a',64)));
 snap:=public.case_control_snapshot(c,actor,false);op:=gen_random_uuid();
 PERFORM public.case_control_apply(c,actor,snap->>'revision','approval',op,ev,'{"decision":"approved","snapshotId":"material"}');
 PERFORM public.case_control_apply(c,actor,snap->>'revision','approval',op,ev,'{"decision":"approved","snapshotId":"material"}');
 blocked:=false;BEGIN PERFORM public.case_control_apply(c,actor,snap->>'revision','approval',op,ev,'{"decision":"rejected","reason":"different"}'); EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_IDEMPOTENCY_CONFLICT' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_OPERATION_REUSE'; END IF;
 INSERT INTO runtime_qa_result VALUES('approval idempotency and conflicting key denied',true);
 snap:=public.case_control_snapshot(c,actor,false);blocked:=false;
 BEGIN PERFORM public.case_control_apply(c,actor,snap->>'revision','close',gen_random_uuid(),ev,'{}'); EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_CLOSURE_NOT_ALLOWED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_EARLY_CLOSE'; END IF;
 INSERT INTO runtime_qa_result VALUES('manual close blocked before all conditions',true);
 blocked:=false;BEGIN PERFORM public.claim_participant_completion(d,ref,actor,'qa@example.invalid','signature','autografa','qa-premature-signature-operation',null,null);EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_SIGNATURE_NOT_READY' THEN blocked:=true; ELSE RAISE; END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_EARLY_PROVIDER_CLAIM'; END IF;
 INSERT INTO runtime_qa_result VALUES('canonical ledger denies signing before its case phase',true);
 ev:=ev||'{"canSign":true,"signingStarted":false}';snap:=public.case_control_snapshot(c,actor,false);
 PERFORM public.case_control_apply(c,actor,snap->>'revision','signatures',gen_random_uuid(),ev,'{}');
 IF (SELECT status FROM public.case_files WHERE id=c)<>'ready_to_sign' THEN RAISE EXCEPTION 'QA_SIGN_PHASE'; END IF;
 -- Provider evidence is synthetic; claim/commit/role/version/idempotency RPCs are real.
 result:=public.claim_participant_completion(d,ref,actor,'qa@example.invalid','signature','autografa','qa-runtime-signature-operation',null,null);attempt:=(result->>'attemptId')::uuid;
 blocked:=false;BEGIN PERFORM public.commit_participant_completion(attempt,actor,'qa@example.invalid','qa-runtime-signature-operation',null,'{}');EXCEPTION WHEN not_null_violation THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_UNSIGNED_COMMIT'; END IF;
 INSERT INTO public.signature_evidence(workspace_id,document_id,document_version_id,participant_record_id,captured_by,evidence_type,evidence_role,document_sha256,signature_hash)
 VALUES(w,d,v,actor,actor,'autograph_signature','FINAL_SIGNATURE',repeat('a',64),repeat('b',64)) RETURNING id INTO evidence;
 PERFORM public.commit_participant_completion(attempt,actor,'qa@example.invalid','qa-runtime-signature-operation',evidence,jsonb_build_object('participant_record_id',actor,'participante_nombre','QA','consent_accepted',true,'consent_accepted_at',now(),'signature_method','autografa','signature_hash',repeat('b',64)));
 result:=public.commit_participant_completion(attempt,actor,'qa@example.invalid','qa-runtime-signature-operation',evidence,'{}');
 IF (result->>'idempotent')::boolean IS DISTINCT FROM true OR (SELECT count(*) FROM public.participation_responses WHERE completion_attempt_id=attempt)<>1 THEN RAISE EXCEPTION 'QA_SIGNATURE_RETRY'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.case_file_tasks WHERE case_file_id=c AND title='case_runtime:refresh' AND status='pending') THEN RAISE EXCEPTION 'QA_DURABLE_CALLBACK'; END IF;
 INSERT INTO runtime_qa_result VALUES('real canonical claim/commit and durable refresh',true);
 SELECT runtime_subject_id INTO subject FROM public.case_files WHERE id=c;
 INSERT INTO public.case_file_invitations(workspace_id,case_file_id,participant_id,verification_id,token_hash,recipient,delivery_status,expires_at,created_by)
 VALUES(w,c,subject,'email','salt:qa-hash','qa@example.invalid','sent',now()+interval '10 minutes',actor) RETURNING id INTO evidence;
 IF public.case_control_otp(c,actor,evidence,false) THEN RAISE EXCEPTION 'QA_BAD_OTP'; END IF;
 IF (SELECT otp_attempts FROM public.case_file_invitations WHERE id=evidence)<>1 THEN RAISE EXCEPTION 'QA_OTP_ATTEMPTS'; END IF;
 IF NOT public.case_control_otp(c,actor,evidence,true) OR public.case_control_otp(c,actor,evidence,true) THEN RAISE EXCEPTION 'QA_OTP_SCOPE'; END IF;
 INSERT INTO runtime_qa_result VALUES('scoped one-use email challenge and attempts',true);
 ev:=ev||'{"readyStageIds":["manual"]}';snap:=public.case_control_snapshot(c,actor,false);
 PERFORM public.case_control_apply(c,actor,snap->>'revision','stage',gen_random_uuid(),ev,'{"stageId":"manual"}');
 IF NOT EXISTS(SELECT 1 FROM public.case_file_milestones WHERE case_file_id=c AND status='completed') THEN RAISE EXCEPTION 'QA_STAGE'; END IF;
 INSERT INTO runtime_qa_result VALUES('manual stage completion',true);
 ev:=ev||'{"eligible":true,"conditions":[{"key":"all","status":"satisfied"}]}';snap:=public.case_control_snapshot(c,actor,false);op:=gen_random_uuid();
 PERFORM public.case_control_apply(c,actor,snap->>'revision','close',op,ev,'{}');
 result:=public.case_control_apply(c,actor,snap->>'revision','close',op,ev,'{}');
 IF result->>'status'<>'sealed' OR (SELECT count(*) FROM public.case_file_closure_manifests WHERE case_file_id=c)<>1 THEN RAISE EXCEPTION 'QA_CLOSE_ONCE'; END IF;
 manifest:=public.case_control_manifest(c,actor);
 IF encode(extensions.digest(manifest->>'content','sha256'),'hex') IS DISTINCT FROM manifest->>'sha256' THEN RAISE EXCEPTION 'QA_MANIFEST_HASH'; END IF;
 blocked:=false;BEGIN UPDATE public.case_files SET title='forbidden' WHERE id=c;EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_CLOSED_MUTATION'; END IF;
 INSERT INTO runtime_qa_result VALUES('single immutable close and reproducible manifest digest',true);
 -- A new publication cannot alter the pinned policy of an existing instance.
 SELECT updated_at INTO old_revision FROM public.case_file_templates WHERE id=t;
 payload:=jsonb_set(payload,'{requirements_schema,reviewPolicy,completion}','{"mode":"automatic","role":null}');
 payload:=jsonb_set(payload,'{requirements_schema,reviewPolicy,approval}','{"enabled":false,"role":null}');
 payload:=jsonb_set(payload,'{requirements_schema,verifications}','[]');
 payload:=jsonb_set(payload,'{requirements_schema,stages}','[]');
 payload:=jsonb_set(payload,'{requirements_schema,sections,0,items,0,requiresReview}','false');
 payload:=jsonb_set(payload,'{requirements_schema,sections,0,items,0,requiresSignature}','false');
 PERFORM public.case_control_publish(t,actor,w,old_revision::timestamptz,payload);
 snap:=public.case_control_snapshot(c,actor,false);
 IF snap#>>'{template,requirements_schema,reviewPolicy,completion,mode}'<>'manual' THEN RAISE EXCEPTION 'QA_PINNED_POLICY'; END IF;
 c:=gen_random_uuid();
 PERFORM public.case_control_start(t,actor,'QA AUTO RUNTIME ROLLBACK','QA sujeto',actor,'{}',c,'qa@example.invalid');
 snap:=public.case_control_snapshot(c,actor,false);
 PERFORM public.case_control_attach(c,actor,snap->>'revision','item',d,'document',gen_random_uuid());
 snap:=public.case_control_snapshot(c,actor,false);
 PERFORM public.case_control_apply(c,actor,snap->>'revision','refresh',gen_random_uuid(),ev,'{}');
 IF (SELECT status FROM public.case_files WHERE id=c)<>'sealed' THEN RAISE EXCEPTION 'QA_AUTOMATIC_CLOSE'; END IF;
 INSERT INTO runtime_qa_result VALUES('automatic close and immutable instance policy',true);
 blocked:=false;BEGIN PERFORM public.case_control_snapshot(c,gen_random_uuid(),false);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_FOREIGN_ACTOR'; END IF;
 INSERT INTO runtime_qa_result VALUES('foreign actor denied at trusted RPC boundary',true);
END $$;
RESET ROLE;
DO $$
DECLARE f runtime_qa_context; form_id uuid:=gen_random_uuid(); token_id uuid; response_id uuid; type_id uuid:=gen_random_uuid(); case_id uuid:=gen_random_uuid(); snap jsonb; payload jsonb; actual_email text;
BEGIN
 SELECT * INTO f FROM runtime_qa_context;
 SELECT email INTO actual_email FROM auth.users WHERE id=f.actor;
 EXECUTE 'SET LOCAL ROLE service_role';
 INSERT INTO public.form_templates(id,workspace_id,name,created_by,status,schema) VALUES(form_id,f.workspace,'QA FORM ROLLBACK',f.actor,'draft','[{"id":"signature","type":"signature_block","required":true}]');
 UPDATE public.form_templates SET status='published' WHERE id=form_id;
 INSERT INTO public.form_tokens(template_id,recipient_email,used_at) VALUES(form_id,actual_email,now()) RETURNING id INTO token_id;
 INSERT INTO public.form_responses(token_id,template_id,workspace_id,response_data,field_hashes,respondent_email,submitted_at,status,pdf_output_hash) VALUES(token_id,form_id,f.workspace,'{}','{}',actual_email,now(),'pdf_generated',repeat('c',64)) RETURNING id INTO response_id;
 payload:=jsonb_build_object('name','QA FORM ADAPTER ROLLBACK','description','','case_type','QA','requirements_schema',jsonb_build_object('version',6,'sections',jsonb_build_array(jsonb_build_object('id','section','title','QA','items',jsonb_build_array(jsonb_build_object('id','form-item','kind','form','sourceId',form_id,'sourceVersion','1','sourceRevision',1,'title','QA respuesta','required',true,'requiresReview',false)))),'stages','[]'::jsonb,'verifications','[]'::jsonb,'reviewPolicy',jsonb_build_object('version',1,'reviewTiming','progressive','approval',jsonb_build_object('enabled',false),'completion',jsonb_build_object('mode','automatic'))),'forms_schema','[]'::jsonb);
 PERFORM public.case_control_publish(type_id,f.actor,f.workspace,null,payload);
 PERFORM public.case_control_start(type_id,f.actor,'QA FORM ADAPTER ROLLBACK','QA sujeto',f.actor,'{}',case_id,'');
 snap:=public.case_control_snapshot(case_id,f.actor,false);
 PERFORM public.case_control_attach(case_id,f.actor,snap->>'revision','form-item',response_id,'form',gen_random_uuid());
 snap:=public.case_control_snapshot(case_id,f.actor,false);
 IF snap#>>'{responses,0,respondent_user_id}' IS DISTINCT FROM f.actor::text OR jsonb_array_length(snap->'submissions')<>1 THEN RAISE EXCEPTION 'QA_REAL_FORM_SUBJECT'; END IF;
 INSERT INTO runtime_qa_result VALUES('pdf_generated form response and legacy authenticated subject resolution',true);
 case_id:=gen_random_uuid();
 INSERT INTO public.form_tokens(template_id,recipient_email,access_mode,used_at) VALUES(form_id,'qa-public@example.invalid','public',now()) RETURNING id INTO token_id;
 INSERT INTO public.form_responses(token_id,template_id,workspace_id,response_data,field_hashes,respondent_email,submitted_at,status,pdf_output_hash) VALUES(token_id,form_id,f.workspace,'{}','{}','qa-public@example.invalid',now(),'pdf_generated',repeat('d',64)) RETURNING id INTO response_id;
 PERFORM public.case_control_start(type_id,f.actor,'QA PUBLIC FORM ROLLBACK','QA externo',null,'{}',case_id,'qa-public@example.invalid');
 snap:=public.case_control_snapshot(case_id,f.actor,false);
 PERFORM public.case_control_attach(case_id,f.actor,snap->>'revision','form-item',response_id,'form',gen_random_uuid());
 snap:=public.case_control_snapshot(case_id,f.actor,false);
 IF (snap#>>'{responses,0,subject_matched}')::boolean IS DISTINCT FROM true OR snap#>>'{participants,0,user_id}' IS NOT NULL THEN RAISE EXCEPTION 'QA_PUBLIC_CONTACT_BINDING'; END IF;
 INSERT INTO runtime_qa_result VALUES('public invited form receipt binds without creating an account',true);
END $$;
RESET ROLE;
GRANT SELECT ON runtime_qa_context TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub',actor::text,true) FROM runtime_qa_context;
DO $$ DECLARE c runtime_qa_context;blocked boolean:=false; BEGIN
 SELECT * INTO c FROM runtime_qa_context;
 BEGIN PERFORM public.case_control_snapshot(c.instance,c.actor,false); EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_RAW_RPC_EXPOSURE'; END IF;
 blocked:=false;BEGIN UPDATE public.case_files SET status='reopened' WHERE id=c.instance;EXCEPTION WHEN insufficient_privilege THEN blocked:=true;WHEN raise_exception THEN IF SQLERRM='CASE_SERVER_OPERATION_REQUIRED' THEN blocked:=true; ELSE RAISE; END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_RAW_CONTROL_WRITE'; END IF;
 blocked:=false;BEGIN INSERT INTO public.form_responses(token_id,template_id,workspace_id,response_data,field_hashes,respondent_user_id,submitted_at,pdf_output_hash) VALUES(gen_random_uuid(),gen_random_uuid(),c.workspace,'{}','{}',c.actor,now(),repeat('a',64));EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_FORGED_FORM_RECEIPT'; END IF;
END $$;
SELECT set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
DO $$ DECLARE c runtime_qa_context; BEGIN SELECT * INTO c FROM runtime_qa_context;IF EXISTS(SELECT 1 FROM public.case_files WHERE id=c.instance) THEN RAISE EXCEPTION 'QA_CROSS_TENANT_READ'; END IF; END $$;
RESET ROLE;
INSERT INTO runtime_qa_result VALUES('authenticated RPC/write forgery and cross-tenant RLS denied',true);
SELECT jsonb_build_object('passed',count(*),'checks',jsonb_agg(label),'all_rolled_back',true) AS qa_result FROM runtime_qa_result;
ROLLBACK;
